# PostgreSQL Connection Pool Setup in Node.js

Here's a comprehensive guide to setting up a PostgreSQL connection pool with proper configuration:

## Basic Setup with `pg` Package

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Connection pool settings
  max: 20,                      // Maximum number of clients in the pool
  min: 5,                       // Minimum number of clients in the pool
  idleTimeoutMillis: 30000,     // Close idle clients after 30 seconds
  connectionTimeoutMillis: 2000, // Return an error after 2 seconds if connection not established
  maxUses: 7500,                // Close connections after 7500 uses (prevents memory leaks)

  // Statement timeout
  statement_timeout: 10000,      // Abort any statement that takes more than 10 seconds
  query_timeout: 10000,          // Query timeout (client-side)

  // Connection settings
  allowExitOnIdle: false,        // Keep pool alive even if all clients are idle

  // SSL configuration (for production)
  ssl: process.env.NODE_ENV === 'production' ? {
    rejectUnauthorized: false
  } : false
});

// Error handling for the pool
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client', err);
  process.exit(-1);
});

pool.on('connect', (client) => {
  console.log('New client connected to the pool');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

module.exports = pool;
```

## Complete Database Module with Error Handling

```javascript
// db.js
const { Pool } = require('pg');

class Database {
  constructor() {
    this.pool = new Pool({
      host: process.env.DB_HOST || 'localhost',
      port: process.env.DB_PORT || 5432,
      database: process.env.DB_NAME,
      user: process.env.DB_USER,
      password: process.env.DB_PASSWORD,
      max: 20,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
      statement_timeout: 10000,
    });

    this.pool.on('error', (err) => {
      console.error('Unexpected pool error', err);
    });
  }

  // Query with automatic client release
  async query(text, params) {
    const start = Date.now();
    try {
      const result = await this.pool.query(text, params);
      const duration = Date.now() - start;
      console.log('Executed query', { text, duration, rows: result.rowCount });
      return result;
    } catch (error) {
      console.error('Query error', { text, error: error.message });
      throw error;
    }
  }

  // Transaction support
  async transaction(callback) {
    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  // Get a client from the pool (manual management)
  async getClient() {
    const client = await this.pool.connect();
    const query = client.query.bind(client);
    const release = client.release.bind(client);

    // Set a timeout to prevent client leaks
    const timeout = setTimeout(() => {
      console.error('A client has been checked out for more than 5 seconds!');
    }, 5000);

    // Override release to clear timeout
    client.release = () => {
      clearTimeout(timeout);
      client.release = release;
      return release();
    };

    return client;
  }

  // Health check
  async healthCheck() {
    try {
      const result = await this.pool.query('SELECT NOW()');
      return { healthy: true, timestamp: result.rows[0].now };
    } catch (error) {
      return { healthy: false, error: error.message };
    }
  }

  // Get pool stats
  getStats() {
    return {
      total: this.pool.totalCount,
      idle: this.pool.idleCount,
      waiting: this.pool.waitingCount
    };
  }

  // Graceful shutdown
